// src/pages/notifications/NotificationStatsPage.jsx
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { fetchAlertStats } from '../../api/NotificationsApi';

function NotificationStatsPage() {
  const navigate = useNavigate();

  const [range, setRange] = useState('daily'); // daily | weekly
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const [series, setSeries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetchAlertStats({ range, from, to });
      setSeries(res.series || []);
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [range]);

  const totals = useMemo(() => {
    const t = { danger: 0, warning: 0 };
    for (const p of series) {
      t.danger += Number(p.danger || 0);
      t.warning += Number(p.warning || 0);
    }
    return t;
  }, [series]);

  const maxVal = useMemo(() => {
    let m = 1;
    for (const p of series) {
      m = Math.max(m, Number(p.danger || 0), Number(p.warning || 0));
    }
    return m;
  }, [series]);

  return (
    <div className="page-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <h1>알림 통계</h1>
        <button className="btn" onClick={() => navigate('/notifications')}>
          목록
        </button>
      </div>

      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          range
          <select value={range} onChange={(e) => setRange(e.target.value)}>
            <option value="daily">daily</option>
            <option value="weekly">weekly</option>
          </select>
        </label>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          from
          <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
        </label>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          to
          <input type="date" value={to} onChange={(e) => setTo(e.target.value)} />
        </label>

        <button className="btn" onClick={load}>조회</button>
      </div>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>에러: {String(error.message || error)}</p>}

      {!loading && !error && (
        <>
          <p style={{ opacity: 0.85 }}>
            합계: <strong>DANGER</strong> {totals.danger} / <strong>WARNING</strong> {totals.warning}
          </p>

          {series.length === 0 ? (
            <p>표시할 데이터가 없습니다.</p>
          ) : (
            <div style={{ overflowX: 'auto', paddingTop: 8 }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr>
                    <th style={{ textAlign: 'left', borderBottom: '1px solid #eee', padding: 8 }}>date</th>
                    <th style={{ textAlign: 'right', borderBottom: '1px solid #eee', padding: 8 }}>warning</th>
                    <th style={{ textAlign: 'right', borderBottom: '1px solid #eee', padding: 8 }}>danger</th>
                    <th style={{ borderBottom: '1px solid #eee', padding: 8 }}>bar</th>
                  </tr>
                </thead>
                <tbody>
                  {series.map((p) => {
                    const w = Number(p.warning || 0);
                    const d = Number(p.danger || 0);
                    const wPct = Math.round((w / maxVal) * 100);
                    const dPct = Math.round((d / maxVal) * 100);
                    return (
                      <tr key={p.date}>
                        <td style={{ padding: 8, borderBottom: '1px solid #f3f3f3' }}>{p.date}</td>
                        <td style={{ padding: 8, textAlign: 'right', borderBottom: '1px solid #f3f3f3' }}>{w}</td>
                        <td style={{ padding: 8, textAlign: 'right', borderBottom: '1px solid #f3f3f3' }}>{d}</td>
                        <td style={{ padding: 8, borderBottom: '1px solid #f3f3f3' }}>
                          <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
                            <div style={{ height: 10, width: `${wPct}%`, background: 'rgba(255,165,0,0.55)', borderRadius: 4 }} />
                            <div style={{ height: 10, width: `${dPct}%`, background: 'rgba(255,0,0,0.55)', borderRadius: 4 }} />
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              <p style={{ opacity: 0.7, marginTop: 8 }}>
                * 막대는 해당 구간의 WARNING(주황) / DANGER(빨강) 상대 크기입니다.
              </p>
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default NotificationStatsPage;
